291	  const { checkBudget } = require('../compactor/budget');
292	  const computeBudgetHealth = (agent) => {
293	    try {
294	      if (!agent.raw) return null;
295	      const agentId = agent.filename.replace(/\.md$/, '');
296	      const check = checkBudget({ agentId, content: agent.raw });
297	      const linePct = check.actual.lines / Math.max(1, check.budget.lines);
298	      const charPct = check.actual.chars / Math.max(1, check.budget.chars);
299	      const usage = Math.max(linePct, charPct);
300	      let status = 'healthy';
301	      if (check.violations.length > 0) status = 'over';
302	      else if (check.warnings.length > 0) status = 'warning';
303	      else if (usage < 0.2) status = 'sparse';
304	      const estimatedTokens = Math.ceil(agent.raw.length / 4);
305	      return {
306	        status,
307	        usage,
308	        actual: check.actual,
309	        budget: check.budget,
310	        violations: check.violations,
311	        warnings: check.warnings,
312	        estimatedTokens,
313	        sizeKb: Math.round((agent.raw.length / 1024) * 100) / 100,
314	      };
315	    } catch (err) {
316	      console.error(`[health] Failed to compute budget health for agent "${agent.filename}":`, err.message);
317	      return null;
318	    }
319	  };
320	
321	  const enrich = (agent) => {
322	    const rec = registryById[agent.filename] || null;
323	    const dept = rec?.department || null;
324	    const deptInfo = dept ? departmentsById[dept] : null;
325	    const subDept = rec?.subDepartment || null;
326	    const subDeptInfo = subDept && deptInfo?.subDepartments
327	      ? deptInfo.subDepartments[subDept] || null
328	      : null;
329	    const health = computeBudgetHealth(agent);
330	    return {
331	      ...agent,
332	      org: rec ? {
333	        level: rec.level ?? null,
334	        levelTitle: rec.levelTitle ?? null,
335	        yearsOfExperience: rec.yearsOfExperience ?? null,
336	        experiencePoints: rec.experiencePoints ?? null,
337	        tier: rec.tier || null,
338	        title: rec.title || null,
339	        status: rec.status || null,
340	        department: dept,
341	        departmentLabel: deptInfo?.label || null,
342	        departmentColor: deptInfo?.color || null,
343	        subDepartment: subDept,
344	        subDepartmentLabel: subDeptInfo?.label || null,
345	        subDepartmentDescription: subDeptInfo?.description || null,
346	        pod: rec.pod || null,
347	        reportsTo: rec.reportsTo || null,
348	        secondaryReportsTo: rec.secondaryReportsTo || null,
349	        squad: rec.squad || null,
350	        isLeader: Boolean(deptInfo && deptInfo.head === agent.filename),
351	        isSubLeader: Boolean(subDept === 'lead' || (subDeptInfo && rec.tier === 'leadership')),
352	      } : null,
353	      health,
354	    };
355	  };
356	
357	  const results = [];
358	  const globalAgents = listAgents(path.join(CLAUDE_DIR, 'agents'));
359	  for (const agent of globalAgents) {
360	    results.push(enrich({ ...agent, scope: 'global', scopeLabel: 'Global', projectId: null, projectName: null }));
361	  }
362	
363	  for (const project of projects) {
364	    for (const agent of project.agents) {
365	      results.push(enrich({ ...agent, scope: 'project', scopeLabel: project.name, projectId: project.id, projectName: project.name }));
366	    }
367	  }
368	
369	  const { category, tags } = req.query;
370	  let filtered = results;
