377	      const agentTags = (a.frontmatter?.tags || '').split(',').map(t => t.trim().toLowerCase());
378	      return tagList.some(t => agentTags.includes(t));
379	    });
380	  }
381	
382	  filtered.sort((a, b) => new Date(b.updatedAt) - new Date(a.updatedAt));
383	  res.json(filtered);
384	});
