66	  const heartbeat = setInterval(() => {
67	    try { res.write(': keepalive\n\n'); } catch {}
68	  }, 25000);
69	
70	  const cleanup = () => {
71	    clearInterval(heartbeat);
72	    agentSync.events.off('agent:upsert', onUpsert);
