3	// Agent sync: keep SQLite `agents` table in lockstep with ~/.claude/agents/*.md.
4	// - Chokidar watches the agents dir. add/change/unlink → upsert/remove in registry.
5	// - On every mutation, emits on the shared EventEmitter so SSE clients push live.
6	// - reseedFromDisk() is called on server boot to close any gap from downtime.
7	//
8	// SQLite writes go through org.upsertAgent (which calls db.saveRegistry),
9	// so we inherit the existing transactional semantics and don't duplicate SQL.
10	
11	const fs = require('fs');
12	const path = require('path');
13	const os = require('os');
14	const { EventEmitter } = require('events');
15	const chokidar = require('chokidar');
16	
17	const { parseAgent } = require('./cache');
18	const org = require('../org');
19	
20	const HOME = os.homedir();
21	const AGENTS_DIR = path.join(HOME, '.claude', 'agents');
22	
23	const events = new EventEmitter();
24	events.setMaxListeners(100);
25	
26	let watcher = null;
27	
28	function deriveAgentRecord(parsed) {
29	  if (!parsed) return null;
30	  const { filename, name, description, model, tools } = parsed;
31	  return {
32	    name: name || filename,
33	    description: description || '',
34	    model: model || 'sonnet',
35	    role: typeof tools === 'string' ? tools : Array.isArray(tools) ? tools.join(',') : '',
36	  };
37	}
38	
39	function isAgentFile(p) {
40	  if (!p) return false;
41	  if (!p.endsWith('.md')) return false;
42	  const dir = path.dirname(p);
43	  return path.resolve(dir) === path.resolve(AGENTS_DIR);
44	}
45	
46	function agentIdFromPath(p) {
47	  return path.basename(p, '.md');
48	}
49	
50	function upsertFromDisk(agentId) {
51	  const filePath = path.join(AGENTS_DIR, `${agentId}.md`);
52	  if (!fs.existsSync(filePath)) {
53	    return { ok: false, reason: 'missing' };
54	  }
55	  const parsed = parseAgent(filePath);
56	  if (!parsed) return { ok: false, reason: 'parse_failed' };
57	
58	  const derived = deriveAgentRecord(parsed);
59	  const existing = org.findAgent(agentId);
60	
61	  // Merge: live metadata from disk overrides; org structure (department/phase/
62	  // reportsTo/level/etc.) is preserved from the existing registry record.
63	  // New agents get sensible defaults so they still render in the org chart.
64	  // Status defaults to 'pending' (not 'probation') so HR sees the new arrival
65	  // needs triage — department/reportsTo/tier MUST be assigned before the agent
66	  // is promoted to active. The org chart layout treats `pending` agents with
67	  // no `reportsTo` as "Unassigned" (NOT as a top leader), so a missing field
68	  // can no longer pollute the leadership row.
69	  const patch = {
70	    ...derived,
71	    status: existing?.status || 'pending',
72	    department: existing?.department ?? 'unassigned',
73	    phase: existing?.phase ?? 'unassigned',
74	    reportsTo: existing?.reportsTo ?? null,
75	    title: existing?.title ?? (parsed.description?.slice(0, 80) || 'Agent'),
76	    tier: existing?.tier ?? 'engineer',
77	    level: existing?.level ?? 1,
78	    hiredAt: existing?.hiredAt || new Date().toISOString(),
79	  };
80	
81	  const saved = org.upsertAgent(agentId, patch);
82	  events.emit('agent:upsert', { agentId, agent: saved });
83	  if (!existing) {
84	    console.warn(
85	      `[agentSync] New disk-only agent "${agentId}" seeded with defaults — assign department/reportsTo/tier in registry.json`
86	    );
87	  }
88	  return { ok: true, agent: saved, isNew: !existing };
89	}
