91	function markRemoved(agentId) {
92	  const existing = org.findAgent(agentId);
93	  if (!existing) return { ok: false, reason: 'not_in_registry' };
94	  // Preserve the record; mark retired so history + reportsTo edges stay intact.
95	  const saved = org.upsertAgent(agentId, {
96	    status: 'retired',
97	    retiredAt: new Date().toISOString(),
98	    retiredReason: 'file_removed_from_disk',
99	  });
100	  events.emit('agent:remove', { agentId, agent: saved });
101	  return { ok: true, agent: saved };
102	}
