104	function reseedFromDisk() {
105	  const summary = { scanned: 0, upserted: 0, removed: 0, errors: [] };
106	  if (!fs.existsSync(AGENTS_DIR)) {
107	    return summary;
108	  }
109	  const files = fs.readdirSync(AGENTS_DIR).filter((f) => f.endsWith('.md'));
110	  summary.scanned = files.length;
111	
112	  const diskIds = new Set();
113	  for (const f of files) {
114	    const id = f.replace(/\.md$/, '');
115	    diskIds.add(id);
116	    try {
117	      const r = upsertFromDisk(id);
118	      if (r.ok) summary.upserted += 1;
119	      else summary.errors.push({ id, reason: r.reason });
120	    } catch (err) {
121	      summary.errors.push({ id, reason: err.message });
122	    }
123	  }
124	
125	  // Retire any active agent whose file was deleted while the server was off.
126	  try {
127	    for (const record of org.listAgentRecords()) {
128	      if (record.status === 'retired') continue;
129	      if (!diskIds.has(record.id)) {
130	        markRemoved(record.id);
131	        summary.removed += 1;
132	      }
133	    }
134	  } catch (err) {
135	    summary.errors.push({ id: '<reconcile>', reason: err.message });
136	  }
137	
138	  return summary;
139	}
