141	function startWatcher() {
142	  if (watcher) return watcher;
143	  if (!fs.existsSync(AGENTS_DIR)) {
144	    console.warn(`[agentSync] agents dir missing: ${AGENTS_DIR} — watcher not started`);
145	    return null;
146	  }
147	
148	  // Gotchas we hit:
149	  //  1. `awaitWriteFinish` + `depth:0` silently drop all events on macOS.
150	  //  2. A dotfile regex like `/(^|[\/\\])\../` also matches `.claude` in the
151	  //     watch path's parent, so chokidar excludes the whole dir. Use a function
152	  //     that only ignores dotfiles at leaf level.
153	  watcher = chokidar.watch(AGENTS_DIR, {
154	    persistent: true,
155	    ignoreInitial: true,
156	    ignored: (p) => path.basename(p).startsWith('.'),
157	  });
158	
159	  // Per-file debounce — collapses a burst (create → chmod → rename) into one.
160	  const pending = new Map();
161	  const schedule = (id, fn) => {
162	    const existing = pending.get(id);
163	    if (existing) clearTimeout(existing);
164	    pending.set(id, setTimeout(() => {
165	      pending.delete(id);
166	      try { fn(); } catch (err) { console.warn(`[agentSync] handler ${id}: ${err.message}`); }
167	    }, 150));
168	  };
169	
170	  const handleAddChange = (p) => {
171	    if (!isAgentFile(p)) return;
172	    const id = agentIdFromPath(p);
173	    schedule(id, () => {
174	      const r = upsertFromDisk(id);
175	      if (r.ok) console.log(`[agentSync] ${r.isNew ? 'added' : 'updated'}: ${id}`);
176	    });
177	  };
178	
179	  const handleUnlink = (p) => {
180	    if (!isAgentFile(p)) return;
181	    const id = agentIdFromPath(p);
182	    schedule(id, () => {
183	      const r = markRemoved(id);
184	      if (r.ok) console.log(`[agentSync] retired: ${id}`);
185	    });
186	  };
187	
188	  watcher.on('add', handleAddChange);
189	  watcher.on('change', handleAddChange);
190	  watcher.on('unlink', handleUnlink);
191	  watcher.on('error', (err) => console.warn(`[agentSync] watcher error: ${err.message}`));
192	  watcher.on('ready', () => console.log(`[agentSync] watcher ready (${Object.keys(watcher.getWatched()).length} dirs)`));
193	  if (process.env.AGENT_SYNC_DEBUG) {
194	    watcher.on('all', (ev, p) => console.log(`[agentSync:raw] ${ev} ${p}`));
195	  }
196	
197	  console.log(`[agentSync] watching ${AGENTS_DIR}`);
198	  return watcher;
199	}
200	
201	function stopWatcher() {
202	  if (watcher) {
203	    watcher.close();
204	    watcher = null;
205	  }
206	}
